def solve(n):
    def multiply(a, b):
        return [
            [a[0]*b[0] + a[1]*b[2], a[0]*b[1] + a[1]*b[3]],
            [a[2]*b[0] + a[3]*b[2], a[2]*b[1] + a[3]*b[3]]
        ]

    def matrix_power(matrix, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, matrix)
            matrix = multiply(matrix, matrix)
            power //= 2
        return result

    if n == 0:
        return 0
